style.css:
@-moz-document domain("open.spotify.com") {
/* Performance optimization - limit transitions to specific elements */
    .main-card-card,
    .main-playButton-button,
    .Button-sc-1dqy6lx-0,
    .main-trackList-trackListRow,
    .main-trackList-trackListRowGrid,
    .sidebar-listItem,
    button {
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
    }

    /* Primary text colors - Baby Pink theme */
    .main-type-mestoBold,
    .main-type-canon,
    .main-type-cello,
    .main-type-alto,
    .main-entityTitle-title,
    .main-entityTitle-subtitle,
    .sidebar-listItem-text,
    .main-trackInfo-name,
    .main-trackInfo-artists,
    .main-type-balladBold,
    .main-type-finale,
    h1, h2, h3, h4, h5, h6 {
        color: #E0115F !important;
    }

    /* Secondary text - complementary light pink */
    .main-type-viola,
    .main-type-ballad,
    .main-type-minuet,
    .sidebar-listItem-subtitle,
    .main-trackList-rowSubTitle,
    .main-trackInfo-artists a,
    .main-type-mesto,
    span[data-testid="entitySubTitle"],
    .main-cardSubHeader-root {
        color: #FFB6E1 !important;
    }

    /* Interface cards and containers - optimized backgrounds */
    .main-card-card,
    .main-shelf-shelf,
    .contentSpacing,
    .main-entityHeader-container,
    .main-gridContainer-gridContainer,
    .main-card-CardButton {
        background: rgba(248, 187, 208, 0.08) !important;
        border: 1px solid rgba(248, 187, 208, 0.15) !important;
        border-radius: 8px !important;
        backdrop-filter: none !important; /* Remove expensive backdrop filter */
    }

    /* Sidebar styling */
    .main-navBar-navBar,
    .main-yourLibraryX-navItem {
        background: rgba(248, 187, 208, 0.05) !important;
        border-radius: 8px !important;
    }

    /* Primary buttons - gradient with baby pink */
    .Button-sc-1dqy6lx-0[data-testid="play-button"],
    .main-playButton-button,
    .main-playButton-PlayButton,
    button[data-testid="play-button"] {
        background: linear-gradient(135deg, #F8BBD0, #FF69B4) !important;
        color: #000000 !important;
        border: none !important;
        box-shadow: 0 2px 8px rgba(248, 187, 208, 0.3) !important;
        border-radius: 50px !important;
    }

    /* Button hover states - performance optimized */
    .Button-sc-1dqy6lx-0[data-testid="play-button"]:hover,
    .main-playButton-button:hover,
    button[data-testid="play-button"]:hover {
        background: linear-gradient(135deg, #FF69B4, #F8BBD0) !important;
        transform: scale(1.05) !important;
        box-shadow: 0 4px 12px rgba(248, 187, 208, 0.4) !important;
    }

    /* Player controls - clean styling */
    .player-controls button,
    .main-playPauseButton-button,
    .main-skipButton-button,
    .main-shuffleButton-button,
    .main-repeatButton-button,
    button[data-testid="control-button-shuffle"],
    button[data-testid="control-button-skip-back"],
    button[data-testid="control-button-playpause"],
    button[data-testid="control-button-skip-forward"],
    button[data-testid="control-button-repeat"] {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
        color: #E0115F !important;
    }

    /* Progress bars */
    .playback-bar__progress-time-elapsed,
    .progress-bar__fg,
    .main-playbackBarRemainingTime-container,
    [data-testid="progress-bar"] .bg-white {
        background: linear-gradient(90deg, #F8BBD0, #FF69B4) !important;
    }

    /* Track list items - optimized hover */
    .main-trackList-trackListRow,
    .main-trackList-trackListRowGrid,
    .main-trackList-trackListRow[role="row"],
    [data-testid="tracklist-row"] {
        background: transparent !important;
        border-bottom: 1px solid rgba(248, 187, 208, 0.1) !important;
    }

    .main-trackList-trackListRow:hover,
    .main-trackList-trackListRowGrid:hover,
    [data-testid="tracklist-row"]:hover {
        background: rgba(248, 187, 208, 0.1) !important;
    }

    /* Icons and SVGs */
    .Svg-sc-ytk21e-0,
    svg[role="img"],
    .main-trackList-rowPlayPause svg,
    .sidebar-listItem svg {
        fill: #E0115F !important;
        color: #E0115F !important;
    }

    /* Search and input fields */
    input,
    .SearchBar__input,
    [data-testid="search-input"],
    .main-searchBox-searchBox input {
        background: rgba(248, 187, 208, 0.1) !important;
        color: #E0115F !important;
        border: 1px solid rgba(248, 187, 208, 0.2) !important;
        border-radius: 20px !important;
    }

    /* Optimized scrollbars */
    ::-webkit-scrollbar {
        width: 6px !important;
    }

    ::-webkit-scrollbar-track {
        background: rgba(248, 187, 208, 0.05) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #E0115F !important;
        border-radius: 3px !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #FF69B4 !important;
    }

    /* Context menus - simplified */
    .react-contextmenu,
    .main-contextMenu-menu,
    [data-testid="context-menu"] {
        background: rgba(20, 20, 20, 0.95) !important;
        border: 1px solid rgba(248, 187, 208, 0.2) !important;
        border-radius: 8px !important;
        /* Removed backdrop-filter for better performance */
    }

    /* Volume slider */
    .volume-bar input[type="range"] {
        background: rgba(248, 187, 208, 0.3) !important;
    }

    /* Now playing bar */
    .main-nowPlayingBar-nowPlayingBar {
        background: rgba(20, 20, 20, 0.95) !important;
        border-top: 1px solid rgba(248, 187, 208, 0.2) !important;
    }

    /* Playlist headers */
    .main-entityHeader-titleText,
    .main-entityHeader-subtitle {
        color: #E0115F !important;
    }

    /* Album covers hover effect - performance optimized */
    .main-card-imageContainer:hover {
        transform: scale(1.02) !important;
    }

    /* Fix for text readability */
    .main-type-caption,
    .main-type-violaBold {
        color: #FFB6E1 !important;
        opacity: 0.9 !important;
    }

    /* Performance: Remove expensive animations on scroll elements */
    .main-rootlist-wrapper,
    .main-gridContainer-gridContainer,
    .os-scrollbar {
        will-change: auto !important;
    }

    /* Optimize like buttons */
    .main-addButton-button,
    .main-trackList-rowHeartButton,
    button[data-testid="add-button"] {
        color: #E0115F !important;
    }

    /* Footer and legal text */
    .main-entityHeader-createdBy,
    .main-entityHeader-metaData {
        color: #FFB6E1 !important;
    }

    /* Fix for middle background yellow issue */
    .main-rootlist-wrapper,
    .main-entityHeader-container,
    .main-view-container,
    [data-testid="rootlist"],
    .contentSpacing {
        background: transparent !important;
    }

    /* Ensure main content area uses proper background */
    .Root__main-view,
    .main-view-container__scroll-node,
    .main-view-container__scroll-node-child {
        background: rgba(20, 20, 20, 0.95) !important;
    }
}

@-moz-document domain("open.spotify.com") {
/* Disable expensive effects on lower-end devices */
    @media (max-width: 1024px) {
        .main-card-card,
        .main-playButton-button {
            box-shadow: none !important;
        }
        
        * {
            transition: none !important;
        }
    }
    
    /* Reduce motion for accessibility */
    @media (prefers-reduced-motion: reduce) {
        * {
            transition: none !important;
            animation: none !important;
            transform: none !important;
        }
    }
}
